// Domain design tokens (resolved server-side by the design system).
const tw = {"page_bg": "bg-[#faf6f0]", "surface": "bg-white", "surface_2": "bg-[#f3ece2]", "heading_text": "text-stone-900", "body_text": "text-stone-600", "muted_text": "text-stone-500", "primary": "bg-amber-800", "primary_hover": "hover:bg-amber-900", "on_primary": "text-amber-50", "border": "border-stone-200", "accent_text": "text-amber-800", "accent_bg": "bg-amber-100", "gradient": "from-amber-700 to-orange-800"};
const RADIUS = "rounded-2xl";
const GRAD = "bg-gradient-to-br from-amber-700 to-orange-800";
const FONT_CSS = ".font-display{font-family: 'Playfair Display', Georgia, serif;} .font-body{font-family: 'Inter', system-ui, sans-serif;} body{font-family: 'Inter', system-ui, sans-serif;}";
const LOGO_URL = "";

// Scroll-reveal wrapper: sections animate in as they enter the viewport
// (IntersectionObserver; no-ops during server render).
function Reveal({ children, delay = 0 }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    const io = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) { setVisible(true); io.disconnect(); }
    }, { threshold: 0.12 });
    io.observe(el);
    // Fallback: embedded/short viewports may never fire the observer
    // (live: preview iframes without scroll) -- never leave content invisible.
    const t = setTimeout(() => { setVisible(true); io.disconnect(); }, 1200);
    return () => { clearTimeout(t); io.disconnect(); };
  }, []);
  return (
    <div
      ref={ref}
      style={{ animationDelay: delay ? `${delay}ms` : undefined }}
      className={`reveal ${visible ? 'reveal-visible' : ''}`}
    >{children}</div>
  );
}

