          ) : (
            <span className={`w-7 h-7 ${GRAD} flex items-center justify-center ${tw.on_primary} font-black text-[11px] ${RADIUS}`}>F&</span>
          )}
          <span className="font-display font-bold">Flour & Salt</span>
        </div>
        &copy; 2026 Flour & Salt. All rights reserved.
      </footer>
    </div>    );
}

