import React, { useState } from 'react';
import { UtensilsCrossed, Clock, MapPin, Phone, Circle as Envelope, Calendar, CheckCircle2, X, Sparkles, ChevronRight } from 'lucide-react';

const initialFormData = {
  name: '',
  email: '',
  phone: '',
  guests: '',
  date: '',
  time: '18:00',
  notes: ''
};

export default function Reservations() {
  const [formData, setFormData] = useState(initialFormData);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isError, setIsError] = useState(false);

  const validate = () => {
    if (!formData.name || !formData.email || !formData.phone || !formData.guests || !formData.date || !formData.time) {
      return 'Please fill in all required fields.';
    }
    return true;
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const validation = validate();
    if (validation !== true) {
      setIsError(true);
      return setTimeout(() => setIsError(false), 2000);
    }

    setIsSubmitting(true);
    setIsError(false);

    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      setTimeout(() => setIsSuccess(false), 2000);
    }, 1200);
  };

  const handleTimeChange = (time) => {
    setFormData({ ...formData, time });
  };

  return (
    <div className="min-h-screen bg-amber-900 text-stone-600 font-sans antialiased">
      {/* Top Gradient Bar */}
      <div className="absolute -top-40 -left-40 w-96 h-96 bg-gradient-to-br from-amber-700 to-orange-800 blur-3xl pointer-events-none animate-pulse" />

      {/* Main Content Container */}
      <div className="relative py-24 sm:py-32 flex flex-col justify-center min-h-screen text-center sm:items-center sm:pt-0">
        {/* Header Gradient Background */}
        <div className="absolute -top-40 -right-40 w-96 h-96 bg-gradient-to-br from-amber-700 to-orange-800 blur-3xl pointer-events-none animate-pulse" />

        {/* Section Headings */}
        <h1 className="font-display text-4xl sm:text-5xl font-extrabold tracking-tight text-transparent bg-clip-text bg-gradient-to-br from-amber-700 to-orange-800 mb-6 sm:mb-8">
          <span className="inline-block animate-pulse">Reservations</span>
        </h1>
        <p className="max-w-md mx-auto text-stone-600 text-base sm:text-lg mb-12 font-medium sm:mb-16">
          Enjoy a cozy corner at Flour & Salt with our elegant table bookings.
        </p>

        {/* Reservation Card */}
        <div className="w-full max-w-md mx-auto bg-[#f3ece2] backdrop-blur-xl border border-stone-200 rounded-2xl p-8 shadow-2xl transition-all duration-500 hover:shadow-3xl">

          {/* Top Decorative Gradient Accent */}
          <div className="h-1.5 bg-gradient-to-br from-amber-700 to-orange-800 rounded-full mb-12" />

          {/* Form Fields */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-stone-600 mb-1">
                Full Name
              </label>
              <input 
                id="name" 
                name="name" 
                value={formData.name} 
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full py-2 px-4 rounded-lg bg-amber-900 border border-stone-200 text-sm placeholder-stone-600 text-stone-600 focus:ring-2 focus:ring-amber-500/20 transition-all duration-200 bg-[#f3ece2]"
                placeholder="Flour & Salt"
                required
              />
            </div>

            <div>
              <label htmlFor="email" className="block text-sm font-medium text-stone-600 mb-1">
                Email Address
              </label>
              <input 
                id="email" 
                name="email" 
                value={formData.email} 
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full py-2 px-4 rounded-lg bg-amber-900 border border-stone-200 text-sm placeholder-stone-600 text-stone-600 focus:ring-2 focus:ring-amber-500/20 transition-all duration-200 bg-[#f3ece2]"
                placeholder="jane@example.com"
                required
              />
            </div>

            <div>
              <label htmlFor="phone" className="block text-sm font-medium text-stone-600 mb-1">
                Phone Number
              </label>
              <input 
                id="phone" 
                name="phone" 
                value={formData.phone} 
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                className="w-full py-2 px-4 rounded-lg bg-amber-900 border border-stone-200 text-sm placeholder-stone-600 text-stone-600 focus:ring-2 focus:ring-amber-500/20 transition-all duration-200 bg-[#f3ece2]"
                placeholder="+1 (555) 123-4567"
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="guests" className="block text-sm font-medium text-stone-600 mb-1">
                  Guest Count
                </label>
                <input 
                  id="guests" 
                  name="guests" 
                  value={formData.guests} 
                  onChange={(e) => setFormData({ ...formData, guests: e.target.value })}
                  className="w-full py-2 px-4 rounded-lg bg-amber-900 border border-stone-200 text-sm placeholder-stone-600 text-stone-600 focus:ring-2 focus:ring-amber-500/20 transition-all duration-200 bg-[#f3ece2]"
                  placeholder="4"
                  required
                />
              </div>
              <div>
                <label htmlFor="date" className="block text-sm font-medium text-stone-600 mb-1">
                  Date & Time
                </label>
                <div className="relative">
                  <input 
                    id="date" 
                    name="date" 
                    type="date" 
                    value={formData.date} 
                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                    className="w-full py-2 px-4 rounded-lg bg-amber-900 border border-stone-200 text-sm placeholder-stone-600 text-stone-600 focus:ring-2 focus:ring-amber-500/20 transition-all duration-200 bg-[#f3ece2]"
                    required
                  />
                  <button 
                    type="button"
                    onClick={() => setFormData({ ...formData, time: '18:00' })}
                    className="absolute right-4 top-1.5 text-amber-400 hover:text-amber-300 transition-colors"
                  >
                    <Clock className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>

            <div className="relative group">
              <label htmlFor="time" className="block text-sm font-medium text-stone-600 mb-1">
                Time Slot
              </label>
              <div className="relative mt-2">
                <select 
                  id="time" 
                  name="time" 
                  value={formData.time} 
                  onChange={(e) => handleTimeChange(e.target.value)}
                  className="w-full py-2 px-4 rounded-lg bg-amber-900 border border-stone-200 text-sm placeholder-stone-600 text-stone-600 focus:ring-2 focus:ring-amber-500/20 transition-all duration-200 bg-[#f3ece2]"
                >
                  <option value="18:00">6:00 PM</option>
                  <option value="19:00">7:00 PM</option>
                  <option value="20:00">8:00 PM</option>
                  <option value="21:00">9:00 PM</option>
                </select>
                <div className="absolute inset-y-0 right-4 flex items-center pointer-events-none">
                  <Sparkles className="w-4 h-4 text-amber-400" />
                </div>
              </div>
            </div>

            {/* Optional Notes */}
            <div className="sm:grid sm:grid-cols-2 sm:gap-4 sm:items-center sm:mt-6">
              <label htmlFor="notes" className="block text-sm font-medium text-stone-600 mb-1">
                Special Requests
              </label>
              <textarea 
                id="notes" 
                name="notes" 
                value={formData.notes} 
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                rows={3}
                className="w-full sm:w-full py-2 px-4 rounded-lg bg-amber-900 border border-stone-200 text-sm placeholder-stone-600 text-stone-600 focus:ring-2 focus:ring-amber-500/20 transition-all duration-200 bg-[#f3ece2]"
                placeholder="None, please."
              />
            </div>

            {/* Submit Button */}
            <button 
              type="submit" 
              disabled={isSubmitting || !formData.name || !formData.email || !formData.phone || !formData.guests || !formData.date || !formData.time}
              className="w-full max-w-xs mx-auto mt-8 bg-amber-600 hover:bg-amber-700 focus:ring-2 focus:ring-amber-900 text-stone-600 font-semibold py-3 rounded-xl transition-all duration-200 border border-amber-700 active:scale-95 group"
            >
              {isSubmitting ? (
                <div className="flex items-center space-x-2">
                  <div className="animate-pulse rounded-full w-5 h-5 bg-[#f3ece2] text-amber-300 group-hover:text-amber-200" />
                  <div className="animate-pulse rounded-full w-8 h-8 bg-[#f3ece2] text-amber-300 group-hover:text-amber-200" />
                </div>
              ) : (
                "Reserve Table"
              )}
            </button>
          </form>

          {/* Success or Error State */}
          {isSuccess && (
            <div className="mt-10 p-4 bg-[#f3ece2] rounded-xl border border-stone-200 flex items-center gap-4 justify-center text-center text-stone-600 transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
              <CheckCircle2 className="w-8 h-8 text-emerald-400" />
              <p className="font-medium text-sm">Your reservation is confirmed!</p>
            </div>
          )}

          {isError && (
            <div className="mt-10 p-4 bg-[#f3ece2] rounded-xl border border-red-500/20 flex items-center gap-4 justify-center text-center text-stone-600 transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
              <X className="w-8 h-8 text-amber-400" />
              <p className="font-medium text-sm">Failed to submit. Please try again.</p>
            </div>
          )}

        </div>

        {/* Bottom Decorative Gradient Accent */}
        <div className="absolute bottom-0 left-0 w-full h-40 bg-gradient-to-br from-amber-700 to-orange-800" />

        {/* Call-to-Action Decorative Glowing Text */}
        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 text-center text-stone-600">
          <span className="inline-flex items-center gap-2 p-1.5 rounded-full bg-[#f3ece2] border border-stone-200 text-sm font-semibold transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
            <Sparkles className="w-4 h-4" /> &nbsp;
            <span>Welcome to Flour & Salt</span>
          </span>
        </div>
      </div>
    </div>
  );
}

