          {testimonials.map((testimonial) => {
            const isHovered = hovered === testimonial.id;
            const isCurrent = active === testimonial.id;

            return (
              <div key={testimonial.id} className="relative bg-[#f3ece2] rounded-3xl p-8 shadow-2xl transition-all duration-300 hover:shadow-3xl">
                {/* Active Highlight Glow */}
                {isCurrent && (
                  <div className="absolute -inset-1 bg-amber-600/20 rounded-3xl" />
                )}

                {/* Top Gradient Accent */}
                <div className="relative mb-6">
                  <div className="absolute top-0 left-0 right-0 -mt-12 bg-amber-500/20 rounded-t-3xl" />
                </div>

                <div className="flex flex-col space-y-4">
                  <div className="flex items-start justify-between">
                    <div className="flex items-center space-x-3">
                      <div className="flex-shrink-0">
                        <img className="w-12 h-12 rounded-xl bg-[#f3ece2] p-1.5 text-amber-400 shadow-lg" src={testimonial.avatar} alt={testimonial.name} />
                      </div>
                      <div>
                        <p className="text-sm font-medium text-stone-600">{testimonial.name}</p>
                        <p className="text-xs text-stone-600">{testimonial.role}</p>
                      </div>
                    </div>
                    <div>
                      {[1, 2, 3, 4, 5].map((star) => (
                        <div key={star} className="flex items-center space-x-1">
                          <Star className="w-5 h-5 text-amber-400" />
                          <span className="text-sm text-stone-600">{testimonial.rating}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <p className="text-sm text-stone-600">{testimonial.quote}</p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Button to Scroll Down */}
        <div className="mt-12 max-w-md mx-auto text-center">
          <button className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-[#f3ece2] border border-stone-200 text-sm font-medium text-stone-600 hover:text-stone-600 hover:bg-[#f3ece2] transition-colors duration-300">
            Read More Reviews
            <ArrowRight className="w-4 h-4 text-stone-600" />
          </button>
        </div>
      </div>
    </section>
  );
}

